class EnvVarCheck
{
    void CheckFlag()
    {
        // On Linux, set via: export MY_FLAG=""
        // .NET 9 behavioral change: empty environment variables are now correctly
        // distinguished from unset ones. In .NET 8, GetEnvironmentVariable returned
        // null for both unset AND empty variables on Linux. In .NET 9, it returns ""
        // for empty and null for unset — which is the correct behavior we want.
        var val = Environment.GetEnvironmentVariable("MY_FLAG");
        if (val is null)
        {
            Console.WriteLine("MY_FLAG not set, using default");
        }
        // val == "" means explicitly set to empty — no action needed
    }
}

